export async function setProjectName(page, projectName) {
    await page.evaluate((name) => {
        const state = JSON.parse(localStorage.getItem('excalidraw-state') || '{}');
        state.name = name;
        state.openDialog = null;
        localStorage.setItem('excalidraw-state', JSON.stringify(state));
        return state.name;
    }, projectName);
}

export async function openSaveToDialog(page) {
    await page.getByTestId("main-menu-trigger").click();
    await page.getByTestId("json-export-button").click();
}

export async function openExportImageDialog(page) {
    await page.getByTestId("main-menu-trigger").click();
    await page.getByTestId("image-export-button").click();
}
